('espace-066', 'classique', 'espace', 'number'::public.question_type, 'Quelle est la hauteur d''Olympus Mons au-dessus du niveau de référence martien, la plus haute montagne du Système solaire ?', 'km', 22, null, false, 'olympus-mons', 'Guinness World Records / NASA', 'https://www.guinnessworldrecords.com/world-records/highest-mountain-in-the-solar-system', false, 2, 'published'::public.question_status, '2026-10-15', null, 'Valeur 22 km conservée mais ambiguë : ~21,9 km au-dessus du niveau de référence de Mars, ~25-26 km au-dessus des plaines environnantes (NASA). Énoncé précisé « au-dessus du niveau de référence martien ».'),
('espace-068', 'classique', 'espace', 'number'::public.question_type, 'Quelle est la distance moyenne entre la Terre et le Soleil, l''astre le plus massif du Système solaire ?', 'millions de km', 150, null, false, 'soleil-distance', 'NASA', 'https://physics.weber.edu/carroll/Phsx1040/HW/HW9Sp08_ans.htm', false, 1, 'published'::public.question_status, '2026-10-15', null, 'Valeur confirmée (149,6 millions de km ≈ 150). Superlatif absent : ajout de « l''astre le plus massif du Système solaire ».'),
('espace-069', 'classique', 'espace', 'number'::public.question_type, 'Combien de secondes met en moyenne la lumière du Soleil, l''étoile la plus proche de la Terre, pour nous parvenir ?', 'secondes', 499, null, false, 'lumiere-soleil', 'NASA', 'https://physics.weber.edu/carroll/Phsx1040/HW/HW9Sp08_ans.htm', false, 2, 'published'::public.question_status, '2026-10-15', null, 'Valeur confirmée (8,32 min ≈ 499 s). Superlatif absent : ajout de « l''étoile la plus proche de la Terre » et « en moyenne ».'),
