('histoire-n3-010', 'classique', 'histoire', 'number'::public.question_type, 'Combien de kilomètres mesurait le mur d’Hadrien, la plus grande frontière fortifiée de l’Empire romain en Bretagne ?', 'km', 117, null, false, 'mur-hadrien', 'English Heritage', 'https://www.english-heritage.org.uk/faqs-hadrians-wall/', false, 2, 'published'::public.question_status, '2026-10-15', null, '73 miles = 80 milles romains ≈ 117 km.'),
